INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 12, 'theory', 'Quiz: a container network by hand');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 12, 0, 'A ping to the bridge gateway works from the namespace, but a ping to 8.8.8.8 says Network is unreachable. What is missing?', '["A MASQUERADE rule on the host", "A default route inside the namespace", "ip_forward=1 on the host", "An enabled lo interface on the host"]', 1, 'The message appears when no route fits the address. The gateway lies in the connected network and is reachable by the network route, while an outside address needs a default route inside the namespace. Forwarding and masquerade are needed later, on the host.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 12, 1, 'tcpdump -n on the host''s outgoing interface shows ping requests with source 10.200.0.2 and no replies. What should you do?', '["Enable ip_forward, otherwise packets will not leave", "Add a second veth end to the namespace", "Add a MASQUERADE rule for the subnet in nat/postrouting", "Restart tcpdump with the -e flag"]', 2, 'Since the packets have left, forwarding works. But the private address 10.200.0.2 is not routed on the internet, so there are no replies: the source must be replaced by the host''s address.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 12, 2, 'In a conntrack line the original tuple is src=10.200.0.2 dst=203.0.113.9 and the reply tuple is src=203.0.113.9 dst=192.168.1.10. What does it mean?', '["Source translation happened: the client looks like 192.168.1.10 to the server", "Destination translation happened: the server is really 192.168.1.10", "NAT was not applied, this is an ordinary connection", "The connection is closed"]', 0, 'The destination in the reply tuple is how the external server sees the client. It differs from the original source, so the sender address was replaced: that is how MASQUERADE works.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 12, 3, 'In which chain of the nat table do you put the DNAT rule for publishing a port that outside packets arrive on?', '["POSTROUTING", "INPUT", "FORWARD", "PREROUTING"]', 3, 'The destination must be changed before the routing decision, so that the packet goes to the namespace and not to a local host process. DNAT is valid in PREROUTING and OUTPUT; POSTROUTING is for source translation.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 12, 4, 'One end of a veth pair on the host is up, and the other inside the namespace is down. What will the up end show?', '["The pair works: either end is enough", "The kernel deleted the pair automatically", "The address disappears and returns when the neighbour is brought up", "No link: if either end is down, the pair is down"]', 3, 'By veth(4), when either end is down, the link state of the pair is down. The up end then usually shows NO-CARRIER. So both ends must be brought up.');
